body.script:
(function () {
  'use strict';
  var HOME = 'https://kkeep.fun/';
  var XHTML = 'http://www.w3.org/1999/xhtml';
  var surface = document.getElementById('surface');
  var loading = document.getElementById('loading');
  var status = document.getElementById('status');
  var slowNote = document.getElementById('slow-note');
  var retry = document.getElementById('retry');
  var tools = document.getElementById('tools');
  var timer;

  function destination(raw) {
    if (!raw) return HOME;
    if (raw.length > 4096) return HOME;
    var decoded = raw;
    try {
      // Validate decoded variants too; encoded slashes must not change the origin.
      for (var i = 0; i < 4; i += 1) {
        if (decoded.charAt(0) !== '/' || decoded.indexOf('//') === 0 || /[\\\u0000-\u001f\u007f]/.test(decoded)) return HOME;
        var next = decodeURIComponent(decoded);
        if (next === decoded) break;
        decoded = next;
      }
      var url = new URL(raw, HOME);
      return url.origin === new URL(HOME).origin ? url.href : HOME;
    } catch (error) {
      return HOME;
    }
  }

  var target = destination(new URLSearchParams(window.location.search).get('path'));
  var directLinks = document.querySelectorAll('[data-direct]');
  for (var i = 0; i < directLinks.length; i += 1) directLinks[i].setAttribute('href', target);

  var frame = document.createElementNS(XHTML, 'iframe');
  frame.setAttribute('id', 'kkeep-frame');
  frame.setAttribute('title', 'Kkeep website');
  frame.setAttribute('allow', 'fullscreen; autoplay; encrypted-media; picture-in-picture; gamepad; clipboard-write');
  frame.setAttribute('allowfullscreen', 'allowfullscreen');
  frame.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
  frame.addEventListener('load', function () {
    // A load event only ends the opening overlay; it does not verify app health.
    window.clearTimeout(timer);
    loading.hidden = true;
  });
  frame.addEventListener('error', showFallback);

  function showFallback() {
    window.clearTimeout(timer);
    loading.hidden = false;
    status.textContent = 'Kkeep is taking longer to open.';
    slowNote.hidden = false;
    retry.hidden = false;
  }

  function openKkeep() {
    window.clearTimeout(timer);
    tools.removeAttribute('open');
    loading.hidden = false;
    status.textContent = 'Opening Kkeep…';
    slowNote.hidden = true;
    retry.hidden = true;
    timer = window.setTimeout(showFallback, 15000);
    frame.setAttribute('src', target);
  }

  retry.addEventListener('click', openKkeep);
  document.getElementById('reload').addEventListener('click', openKkeep);
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') tools.removeAttribute('open');
  });
  document.addEventListener('pointerdown', function (event) {
    if (!tools.contains(event.target)) tools.removeAttribute('open');
  });
  window.addEventListener('blur', function () {
    window.setTimeout(function () {
      if (document.activeElement === frame) tools.removeAttribute('open');
    }, 0);
  });
  openKkeep();
  surface.insertBefore(frame, loading);
})();
